// Keep only mail that plausibly relates to a job application, and reshape it
// into the payload AgenticOS expects. Classification happens in AgenticOS, not here.
const KEYWORDS = [
  'application', 'applied', 'candidate', 'position', 'vacancy', 'role',
  'interview', 'assessment', 'offer', 'recruit', 'hiring', 'careers', 'cv', 'resume',
  'وظيف', 'تقديم', 'مقابلة', 'توظيف', 'طلب', 'اختبار', 'شاغر'
];

const out = [];
for (const item of $input.all()) {
  const mail = item.json;
  const headers = mail.headers || {};
  const subject = mail.subject || headers.subject || '';
  const body = mail.text || mail.textPlain || mail.snippet || '';
  const fromRaw = mail.from?.value?.[0] || {};
  const fromAddress = fromRaw.address || headers.from || '';
  const haystack = `${subject}\n${body}`.toLowerCase();

  if (!KEYWORDS.some(k => haystack.includes(k))) continue;

  out.push({
    json: {
      message_id: mail.id || headers['message-id'] || '',
      source: 'gmail',
      from_name: fromRaw.name || '',
      from_address: fromAddress,
      to_address: mail.to?.value?.[0]?.address || '',
      subject,
      body: body.slice(0, 20000),
      received_at: mail.date || headers.date || new Date().toISOString()
    }
  });
}
return out;
